def process_order(sink: ErrorSink, order_id: str) -> None:
    try:
        _settle(order_id)
    except PaymentDeclined as exc:
        event_id = sink.capture_exception(
            exc,
            level='warning',
            tags={'order.id': order_id, 'payment.gateway': 'stripe'},
            extras={'retry_count': 2},
        )
        _notify_ops(event_id)
        raise
